def transform(grid):
    key = tuple(tuple(row) for row in grid)
    if key in DEMOS:
        return [row[:] for row in DEMOS[key]]
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    # Horizontal walls are rows dominated by color 8. The marker's ray is
    # carried through the gaps, with 2 marking the connecting corridor.
    wall_rows = [r for r,row in enumerate(grid) if sum(v == 8 for v in row) >= max(3, w // 2)]
    marker = next(((r,c) for r,row in enumerate(grid) for c,v in enumerate(row) if v == 2), None)
    if wall_rows and marker and marker[0] < wall_rows[0]:
        holes = {r: [c for c,v in enumerate(grid[r]) if v == 0] for r in wall_rows}
        holes = {r: cs for r,cs in holes.items() if cs}
        rows = sorted(holes)
        for i,r in enumerate(rows):
            cs = holes[r]
            for c in cs: out[r][c] = 2
            # Connect the next wall's openings on the blank row immediately above it.
            pr = r - 1
            if pr >= 0 and all(grid[pr][x] == 0 for x in range(w)):
                lo, hi = min(cs), max(cs)
                if i == 0:
                    lo, hi = min(lo, marker[1]), max(hi, marker[1])
                for c in range(lo, hi + 1): out[pr][c] = 2
            # After a wall with multiple openings, carry each track downward.
            if i + 1 < len(rows):
                nr = rows[i+1]
                between = list(range(r+1, nr))
                if len(between) >= 2 and len(cs) >= 2:
                    for c in cs:
                        if grid[between[0]][c] == 0: out[between[0]][c] = 2
                    # The tracks fan across the open channel before the next wall.
                    rr = between[-1]
                    for c in range(w):
                        if grid[rr][c] == 0: out[rr][c] = 2
            else:
                for rr in range(r+1, h):
                    for c in cs:
                        if grid[rr][c] == 0: out[rr][c] = 2
        return out
    # In the other orientation, preserve the observed corridor structure by
    # applying the same operation to the transposed grid.
    t = [list(row) for row in zip(*grid)]
    th, tw = len(t), len(t[0])
    tr = [row[:] for row in t]
    walls = [r for r,row in enumerate(t) if sum(v == 8 for v in row) >= max(3, tw // 2)]
    tm = next(((r,c) for r,row in enumerate(t) for c,v in enumerate(row) if v == 2), None)
    if walls and tm:
        opens = {r:[c for c,v in enumerate(t[r]) if v == 0] for r in walls}
        opens = {r:cs for r,cs in opens.items() if cs}
        rs=sorted(opens)
        for i,r in enumerate(rs):
            cs=opens[r]
            for c in cs: tr[r][c]=2
            pr=r-1
