                    for c in range(tw):
                        if t[between[-1]][c]==0: tr[between[-1]][c]=2
            else:
                for rr in range(r+1,th):
                    for c in cs:
                        if t[rr][c]==0: tr[rr][c]=2
    return [list(row) for row in zip(*tr)]
